223	  if (success) {
224	    health.consecutiveFailures = 0;
225	    health.healthy = true;
226	    health.circuitOpen = false;
227	    // Update average latency
228	    health.avgLatencyMs = (health.avgLatencyMs * 0.9) + (latencyMs * 0.1);
229	  } else {
