241	/**
242	 * Select model for invocation
243	 */
244	export function selectModel(
245	  tier: ModelTier,
246	  excludeModels: string[] = []
247	): ModelConfig | null {
248	  const models = getModelsForTier(tier);
249	  
250	  for (const model of models) {
251	    if (excludeModels.includes(model.id)) continue;
252	    if (!isModelHealthy(model.id)) continue;
253	    return model;
254	  }
255	  
256	  return null;
257	}
258	
259	/**
260	 * Route model invocation with fallback
261	 */
262	export async function routeModelInvocation<T>(
263	  tier: ModelTier,
264	  context: "release_gate" | "pr_review" | "runtime_observe",
265	  invoker: (model: ModelConfig) => Promise<T>
266	): Promise<ModelInvocationResult & { response?: T }> {
267	  initializeModelHealth();
268	  
269	  const startTime = Date.now();
270	  const triedModels: string[] = [];
271	  let lastError: string | undefined;
272	  
273	  // Try primary model
274	  const primaryModel = selectModel(tier, triedModels);
275	  
276	  if (primaryModel) {
277	    triedModels.push(primaryModel.id);
278	    
279	    try {
280	      const response = await invoker(primaryModel);
281	      const latencyMs = Date.now() - startTime;
282	      
283	      recordModelResult(primaryModel.id, true, latencyMs);
284	      
285	      return {
286	        success: true,
287	        modelUsed: primaryModel.id,
288	        fallbackUsed: false,
289	        degradeMode: false,
290	        response,
291	        latencyMs,
292	      };
293	    } catch (error: unknown) {
294	      lastError = error.message;
295	      recordModelResult(primaryModel.id, false, Date.now() - startTime);
296	    }
297	  }
298	  
299	  // Try fallback models
300	  let fallbackModel = selectModel(tier, triedModels);
301	  
302	  while (fallbackModel) {
303	    triedModels.push(fallbackModel.id);
304	    
305	    try {
306	      const response = await invoker(fallbackModel);
307	      const latencyMs = Date.now() - startTime;
308	      
309	      recordModelResult(fallbackModel.id, true, latencyMs);
310	      
311	      return {
312	        success: true,
313	        modelUsed: fallbackModel.id,
314	        fallbackUsed: true,
315	        degradeMode: false,
316	        response,
317	        latencyMs,
318	      };
319	    } catch (error: unknown) {
320	      lastError = error.message;
321	      recordModelResult(fallbackModel.id, false, Date.now() - startTime);
322	    }
323	    
324	    fallbackModel = selectModel(tier, triedModels);
325	  }
326	  
327	  // All models failed - apply failure mode
328	  const failureMode = routerConfig.failureModeByContext[context];
329	  const latencyMs = Date.now() - startTime;
330	  
331	  if (failureMode === "fail_open") {
332	    return {
333	      success: true, // Fail open = allow through
334	      modelUsed: "none",
335	      fallbackUsed: true,
336	      degradeMode: true,
337	      latencyMs,
338	      error: `All models failed, fail-open applied: ${lastError}`,
339	    };
340	  }
341	  
342	  // fail_closed or degrade
343	  return {
344	    success: false,
345	    modelUsed: "none",
346	    fallbackUsed: true,
347	    degradeMode: failureMode === "degrade",
348	    latencyMs,
349	    error: `All models failed: ${lastError}`,
350	  };
351	}
352	
353	/**
354	 * Deterministic check (no LLM required)
355	 */
356	export function runDeterministicCheck(
357	  checkFn: () => { pass: boolean; violations: string[] }
358	): { pass: boolean; violations: string[]; llmRequired: false } {
359	  const result = checkFn();
360	  return {
361	    ...result,
362	    llmRequired: false,
363	  };
364	}
