378	  routerConfig = { ...routerConfig, ...config };
379	}
380	
381	/**
382	 * Get router configuration
383	 */
384	export function getRouterConfig(): ModelRouterConfig {
385	  return { ...routerConfig };
386	}
387	
388	/**
389	 * Simulate provider outage for testing
390	 */
391	export function simulateProviderOutage(provider: string): void {
392	  for (const [modelId, model] of modelRegistry) {
393	    if (model.provider === provider) {
394	      const health = modelHealth.get(modelId);
395	      if (health) {
396	        health.healthy = false;
397	        health.circuitOpen = true;
398	        health.consecutiveFailures = routerConfig.circuitBreaker.failureThreshold;
399	      }
400	    }
401	  }
402	}
403	
404	/**
405	 * Clear provider outage simulation
406	 */
407	export function clearProviderOutage(provider: string): void {
