/**
 * Model Router v1 - Fallback + Deterministic Split
 * 
 * This module manages LLM model routing:
 * - Deterministic vs LLM split (policy checks always deterministic)
 * - Model tiers (cheap/standard/critical)
 * - Fallback chain (primary → secondary → degrade)
 * - Fail-closed in release_gate, fail-open in runtime_observe
 * 
 * Enterprise killer issue: What happens if OpenAI goes down?
 */

// ============================================================================
// TYPES
// ============================================================================

export type ModelTier = "cheap" | "standard" | "critical";
export type FailureMode = "fail_closed" | "fail_open" | "degrade";

export interface ModelConfig {
  id: string;
  name: string;
  provider: string;
  tier: ModelTier;
  enabled: boolean;
  maxTokens: number;
  costPer1kTokens: number;
  latencyMs: number;
  reliability: number; // 0-1
}

export interface ModelRouterConfig {
  defaultTier: ModelTier;
  failureModeByContext: {
    release_gate: FailureMode;
    pr_review: FailureMode;
    runtime_observe: FailureMode;
  };
  fallbackChain: {
    tier: ModelTier;
    models: string[];
  }[];
  circuitBreaker: {
    enabled: boolean;
    failureThreshold: number;
    resetTimeoutMs: number;
  };
}

export interface ModelInvocationResult {
  success: boolean;
  modelUsed: string;
  fallbackUsed: boolean;
  degradeMode: boolean;
  response?: any;
  error?: string;
  latencyMs: number;
}

export interface ModelHealth {
  modelId: string;
  healthy: boolean;
  lastCheck: Date;
  consecutiveFailures: number;
  circuitOpen: boolean;
  avgLatencyMs: number;
}

// ============================================================================
// MODEL REGISTRY
// ============================================================================

// Built-in model configurations
const modelRegistry: Map<string, ModelConfig> = new Map([
  ["claude-3-opus", {
    id: "claude-3-opus",
    name: "Claude 3 Opus",
    provider: "anthropic",
    tier: "critical",
    enabled: true,
    maxTokens: 4096,
    costPer1kTokens: 0.015,
    latencyMs: 2000,
    reliability: 0.99,
  }],
  ["claude-3-sonnet", {
    id: "claude-3-sonnet",
    name: "Claude 3 Sonnet",
    provider: "anthropic",
    tier: "standard",
    enabled: true,
    maxTokens: 4096,
    costPer1kTokens: 0.003,
    latencyMs: 1000,
    reliability: 0.99,
  }],
  ["claude-3-haiku", {
    id: "claude-3-haiku",
    name: "Claude 3 Haiku",
    provider: "anthropic",
    tier: "cheap",
    enabled: true,
    maxTokens: 4096,
    costPer1kTokens: 0.00025,
    latencyMs: 500,
    reliability: 0.99,
  }],
  ["gpt-4o", {
    id: "gpt-4o",
    name: "GPT-4o",
    provider: "openai",
    tier: "critical",
    enabled: true,
    maxTokens: 4096,
    costPer1kTokens: 0.01,
    latencyMs: 1500,
    reliability: 0.98,
  }],
  ["gpt-4o-mini", {
    id: "gpt-4o-mini",
    name: "GPT-4o Mini",
    provider: "openai",
    tier: "cheap",
    enabled: true,
    maxTokens: 4096,
    costPer1kTokens: 0.00015,
    latencyMs: 400,
    reliability: 0.98,
  }],
]);

// Model health tracking
const modelHealth: Map<string, ModelHealth> = new Map();

// Default router configuration
let routerConfig: ModelRouterConfig = {
  defaultTier: "standard",
  failureModeByContext: {
    release_gate: "fail_closed",
    pr_review: "fail_closed",
    runtime_observe: "fail_open",
  },
  fallbackChain: [
    { tier: "critical", models: ["claude-3-opus", "gpt-4o"] },
    { tier: "standard", models: ["claude-3-sonnet", "gpt-4o"] },
    { tier: "cheap", models: ["claude-3-haiku", "gpt-4o-mini"] },
  ],
  circuitBreaker: {
    enabled: true,
    failureThreshold: 3,
    resetTimeoutMs: 60000,
  },
};

// ============================================================================
// MODEL ROUTER
// ============================================================================

/**
 * Initialize model health tracking
 */
function initializeModelHealth(): void {
  for (const [modelId] of modelRegistry) {
    if (!modelHealth.has(modelId)) {
      modelHealth.set(modelId, {
        modelId,
        healthy: true,
        lastCheck: new Date(),
        consecutiveFailures: 0,
        circuitOpen: false,
        avgLatencyMs: 0,
      });
    }
  }
}

/**
 * Get models for a tier
 */
export function getModelsForTier(tier: ModelTier): ModelConfig[] {
  const tierConfig = routerConfig.fallbackChain.find(c => c.tier === tier);
  if (!tierConfig) return [];

  return tierConfig.models
    .map(id => modelRegistry.get(id))
    .filter((m): m is ModelConfig => m !== undefined && m.enabled);
}

/**
 * Check if model is healthy
 */
export function isModelHealthy(modelId: string): boolean {
  const health = modelHealth.get(modelId);
  if (!health) return false;

  // Check circuit breaker
  if (health.circuitOpen) {
    // Check if reset timeout has passed
    const timeSinceLastCheck = Date.now() - health.lastCheck.getTime();
    if (timeSinceLastCheck < routerConfig.circuitBreaker.resetTimeoutMs) {
      return false;
    }
    // Reset circuit for retry
    health.circuitOpen = false;
  }

  return health.healthy;
}

/**
 * Record model invocation result
 */
export function recordModelResult(
  modelId: string,
  success: boolean,
  latencyMs: number
): void {
  const health = modelHealth.get(modelId);
  if (!health) return;

  health.lastCheck = new Date();

  if (success) {
    health.consecutiveFailures = 0;
    health.healthy = true;
    health.circuitOpen = false;
    // Update average latency
    health.avgLatencyMs = (health.avgLatencyMs * 0.9) + (latencyMs * 0.1);
  } else {
    health.consecutiveFailures++;

    // Check circuit breaker threshold
    if (routerConfig.circuitBreaker.enabled &&
        health.consecutiveFailures >= routerConfig.circuitBreaker.failureThreshold) {
      health.circuitOpen = true;
      health.healthy = false;
    }
  }
}

/**
 * Select model for invocation
 */
export function selectModel(
  tier: ModelTier,
  excludeModels: string[] = []
): ModelConfig | null {
  const models = getModelsForTier(tier);

  for (const model of models) {
    if (excludeModels.includes(model.id)) continue;
    if (!isModelHealthy(model.id)) continue;
    return model;
  }

  return null;
}

/**
 * Route model invocation with fallback
 */
export async function routeModelInvocation<T>(
  tier: ModelTier,
  context: "release_gate" | "pr_review" | "runtime_observe",
  invoker: (model: ModelConfig) => Promise<T>
): Promise<ModelInvocationResult & { response?: T }> {
  initializeModelHealth();

  const startTime = Date.now();
  const triedModels: string[] = [];
  let lastError: string | undefined;

  // Try primary model
  const primaryModel = selectModel(tier, triedModels);

  if (primaryModel) {
    triedModels.push(primaryModel.id);

    try {
      const response = await invoker(primaryModel);
      const latencyMs = Date.now() - startTime;

      recordModelResult(primaryModel.id, true, latencyMs);

      return {
        success: true,
        modelUsed: primaryModel.id,
        fallbackUsed: false,
        degradeMode: false,
        response,
        latencyMs,
      };
    } catch (error: unknown) {
      lastError = error.message;
      recordModelResult(primaryModel.id, false, Date.now() - startTime);
    }
  }

  // Try fallback models
  let fallbackModel = selectModel(tier, triedModels);

  while (fallbackModel) {
    triedModels.push(fallbackModel.id);

    try {
      const response = await invoker(fallbackModel);
      const latencyMs = Date.now() - startTime;

      recordModelResult(fallbackModel.id, true, latencyMs);

      return {
        success: true,
        modelUsed: fallbackModel.id,
        fallbackUsed: true,
        degradeMode: false,
        response,
        latencyMs,
      };
    } catch (error: unknown) {
      lastError = error.message;
      recordModelResult(fallbackModel.id, false, Date.now() - startTime);
    }

    fallbackModel = selectModel(tier, triedModels);
  }

  // All models failed - apply failure mode
  const failureMode = routerConfig.failureModeByContext[context];
  const latencyMs = Date.now() - startTime;

  if (failureMode === "fail_open") {
    return {
      success: true, // Fail open = allow through
      modelUsed: "none",
      fallbackUsed: true,
      degradeMode: true,
      latencyMs,
      error: `All models failed, fail-open applied: ${lastError}`,
    };
  }

  // fail_closed or degrade
  return {
    success: false,
    modelUsed: "none",
    fallbackUsed: true,
    degradeMode: failureMode === "degrade",
    latencyMs,
    error: `All models failed: ${lastError}`,
  };
}

/**
 * Deterministic check (no LLM required)
 */
export function runDeterministicCheck(
  checkFn: () => { pass: boolean; violations: string[] }
): { pass: boolean; violations: string[]; llmRequired: false } {
  const result = checkFn();
  return {
    ...result,
    llmRequired: false,
  };
}

/**
 * Get model health status
 */
export function getModelHealthStatus(): ModelHealth[] {
  initializeModelHealth();
  return Array.from(modelHealth.values());
}

/**
 * Update router configuration
 */
export function updateRouterConfig(config: Partial<ModelRouterConfig>): void {
  routerConfig = { ...routerConfig, ...config };
}

/**
 * Get router configuration
 */
export function getRouterConfig(): ModelRouterConfig {
  return { ...routerConfig };
}

/**
 * Simulate provider outage for testing
 */
export function simulateProviderOutage(provider: string): void {
  for (const [modelId, model] of modelRegistry) {
    if (model.provider === provider) {
      const health = modelHealth.get(modelId);
      if (health) {
        health.healthy = false;
        health.circuitOpen = true;
        health.consecutiveFailures = routerConfig.circuitBreaker.failureThreshold;
      }
    }
  }
}

/**
 * Clear provider outage simulation
 */
export function clearProviderOutage(provider: string): void {
  for (const [modelId, model] of modelRegistry) {
    if (model.provider === provider) {
      const health = modelHealth.get(modelId);
      if (health) {
        health.healthy = true;
        health.circuitOpen = false;
        health.consecutiveFailures = 0;
      }
    }
  }
}

// ============================================================================
// EXPORTS
// ============================================================================

export const ModelRouter = {
  getModelsForTier,
  isModelHealthy,
  recordModelResult,
  selectModel,
  routeModelInvocation,
  runDeterministicCheck,
  getModelHealthStatus,
  updateRouterConfig,
  getRouterConfig,
  simulateProviderOutage,
  clearProviderOutage,
